SELECT
    id, name, main_image, category_id, merchant_id,
    price, original_price, stock, sold_count,
    status, is_recommended, create_time
FROM product


        merchant_id = #{merchantId}


        AND name LIKE CONCAT('%', #{name}, '%')


        AND category_id = #{categoryId}


        AND status = #{status}




